function [tau_M, i_s_out] = mfun_cvc_current_reference_generator(tau_M_ref, u_s_in, u_dc, psi_R_in, p)
%MFUN_CVC_CURRENT_REFERENCE_GENERATOR Block CurrentReferenceGenerator of the control system.
%   CurrentReferenceGenerator of motulator. Generated by motulator_export from the
%   MATLAB port of motulator and called by the MATLAB Function block of the Simulink
%   model, which adds its folder to the MATLAB path. The parameters are the fields of
%   the struct p (from the mask, [] as NaN). The state is in persistent variables, of
%   which each MATLAB Function block has its own copy. The inputs without direct
%   feedthrough come through unit delays, so the update of the state with them is done
%   at the next call.
persistent self pending
if isempty(self)
    % Machine model (InductionMachineInvGammaPars)
    par = struct('n_p', p.par_n_p, 'R_s', p.par_R_s, 'R_R', p.par_R_R, ...
        'L_sgm', p.par_L_sgm, 'L_M', p.par_L_M);
    self = im_reference_gen_init(par, p.psi_s_nom, p.i_s_max, p.w_s_nom, p.k_u, p.k_fw);
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% u_s, u_dc through unit delays)
if pending
    u_s = complex_in(u_s_in);
    % Field weakening based on the unlimited voltage reference
    self = im_reference_gen_update(self, p.T_s, u_s, u_dc);
end
pending = true;
psi_R = complex_in(psi_R_in);
[i_s_ref, tau_M] = im_reference_gen_compute_output(self, tau_M_ref, abs(psi_R));
% Transform the reference to the same coordinates as the feedback
i_s = exp(1i*angle(psi_R))*i_s_ref;
i_s_out = complex_out(i_s);
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function y = clip(value, min_value, max_value)
%CLIP Limit the value into the range [min_value, max_value].
y = max(min(value, max_value), min_value);
end

function self = im_reference_gen_init(par, psi_s_nom, i_s_max, w_s_nom, k_u, k_fw)
%IM_REFERENCE_GEN_INIT Current reference generator with field weakening
%   (CurrentReferenceGenerator); k_fw = NaN means 2*R_R/(w_s_nom*L_sgm^2).
i_sd_nom = psi_s_nom/(par.L_M + par.L_sgm);
if isnan(k_fw)
    k_fw = 2*par.R_R/(w_s_nom*par.L_sgm*par.L_sgm);
end
self = struct('par', par, 'i_s_max', i_s_max, 'k_u', k_u, 'i_sd_nom', i_sd_nom, ...
    'k_fw', k_fw, 'i_sd_ref', i_sd_nom);
end

function [i_s_ref, tau_M_ref_lim] = im_reference_gen_compute_output(self, ...
    tau_M_ref, psi_R)
%IM_REFERENCE_GEN_COMPUTE_OUTPUT Current reference in rotor flux coordinates and
%   the limited torque reference, given the rotor flux magnitude psi_R.
par = self.par;
i_sd_ref = self.i_sd_ref;
% q-axis current reference
if psi_R > 0
    i_sq_ref = tau_M_ref/(1.5*par.n_p*psi_R);
else
    i_sq_ref = 0;
end
% q-axis current limit: priority given to the d component, and the breakdown torque
% limit
i_sq_max1 = sqrt(self.i_s_max*self.i_s_max - i_sd_ref*i_sd_ref);
i_sq_max2 = psi_R/par.L_sgm + i_sd_ref;
i_sq_max = min(i_sq_max1, i_sq_max2);
i_sq_ref = clip(i_sq_ref, -i_sq_max, i_sq_max);
i_s_ref = complex(i_sd_ref, i_sq_ref);
% Limited torque (for the speed controller)
tau_M_ref_lim = 1.5*par.n_p*psi_R*i_sq_ref;
end

function self = im_reference_gen_update(self, T_s, u_s_ref, u_dc)
%IM_REFERENCE_GEN_UPDATE Field weakening based on the unlimited reference voltage.
u_s_max = self.k_u*u_dc/sqrt(3);
self.i_sd_ref = self.i_sd_ref + T_s*self.k_fw*(u_s_max - abs(u_s_ref));
self.i_sd_ref = clip(self.i_sd_ref, -self.i_s_max, self.i_sd_nom);
end
